//! Write/seek sequences in every fopen mode compared with `/usr/bin/php8.5`
//! (generated by `tests/data/gen_writeops.php`; keep the lists in sync).

use php_streams::diag;
use php_streams::file;
use php_streams::open;
use php_streams::stream::Stream;

const SCRIPTS: &[&str] = &[
    "fwrite abc;ftell;fseek 0 0;fread 10;fwrite Z;ftell",
    "fread 2;fwrite XY;ftell;fseek 0 0;fread 100",
    "fseek 10 0;fwrite Q;ftell;fseek 0 0;fread 100",
    "fwrite 12;fseek -1 1;fwrite 3;fseek 0 2;ftell;ftruncate 2;ftell;fwrite W",
    "fgets;fwrite --;fgets;ftell",
];

fn hex(b: &[u8]) -> String {
    use std::fmt::Write;
    b.iter().fold(String::new(), |mut s, c| {
        let _ = write!(s, "{c:02x}");
        s
    })
}

fn enc(v: Option<Vec<u8>>) -> String {
    v.map_or_else(|| "F".to_string(), |b| format!("S{}", hex(&b)))
}

fn run(s: &mut Stream, script: &str) -> Vec<String> {
    let mut out = Vec::new();
    for cmd in script.split(';') {
        let p: Vec<&str> = cmd.splitn(3, ' ').collect();
        let n = |i: usize| p[i].parse::<i64>().unwrap();
        let r = match p[0] {
            "fwrite" => {
                file::fwrite(s, p[1].as_bytes(), None).map_or("F".into(), |v| format!("I{v}"))
            }
            "fread" => enc(file::fread(s, n(1)).unwrap()),
            "fgets" => enc(file::fgets(s, None).unwrap()),
            "ftell" => file::ftell(s).map_or("F".into(), |v| format!("I{v}")),
            "fseek" => format!("I{}", file::fseek(s, n(1), n(2))),
            "ftruncate" => if file::ftruncate(s, n(1)).unwrap() {
                "T"
            } else {
                "F"
            }
            .into(),
            other => panic!("unknown op {other}"),
        };
        for d in diag::take() {
            out.push(format!("E{}", hex(&d.message)));
        }
        out.push(r);
    }
    out
}

#[test]
fn write_ops_match_php() {
    let dir = std::env::temp_dir().join(format!("php-streams-writeops-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("f");
    let pathb = path.to_str().unwrap().as_bytes().to_vec();
    let oracle = include_str!("data/writeops_oracle.txt");
    let mut failures = Vec::new();
    let _ = diag::take();
    for line in oracle.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        let (kind, mode) = (f[0], f[1]);
        let si: usize = f[2].parse().unwrap();
        let _ = std::fs::remove_file(&path);
        if !mode.starts_with('x') {
            std::fs::write(&path, b"hello\nworld\n").unwrap();
        }
        let url: &[u8] = if kind == "file" {
            &pathb
        } else {
            b"php://memory"
        };
        let mut s = open::fopen(url, mode, false, None).unwrap();
        let got = run(&mut s, SCRIPTS[si]).join(",");
        s.close();
        let fin = if kind == "file" {
            hex(&std::fs::read(&path).unwrap())
        } else {
            "-".into()
        };
        if got != f[3] || fin != f[4] {
            failures.push(format!(
                "{kind} {mode} {:?}\n  php:  {} / {}\n  ours: {got} / {fin}",
                SCRIPTS[si], f[3], f[4]
            ));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
